        this._activeSlot = -1;
        this._slotOffset = 0;
        this._sabNeedDataPending = false;
        this._totalWritten = 0;
        this._queue.length = 0;
        if (this._debug) console.log("[Worklet] SAB mode, slots: " + msg.numSlots + ", slotLen: " + this._slotLength);
